#!/usr/bin/env node

// source_reference: fail-closed rollback for synthetic Controle de Voos staging E2E fixtures.
// Differences from the legacy cleanup:
// - removes domain_events generated by synthetic funcionario audit publishing;
// - removes auth refresh tokens created by real staging logins before usuarios;
// - removes audit rows tied to synthetic users/domain events before parent rows;
// - removes funcionarios/setores before synthetic usuarios/empresas;
// - reports the exact failing cleanup label and stops;
// - preserves the manifest on any failure so cleanup can be retried;
// - verifies that synthetic tenants/users/auth/domain records are gone before deleting the manifest.

import { readFileSync, rmSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import { spawnSync } from 'node:child_process';

const ALLOWED_D1_NAME = 'airtrust-db-staging-baseline-20260701';
const WORKER_DIR = decodeURIComponent(new URL('../../worker-airtrust/', import.meta.url).pathname);

function log(message) {
  process.stderr.write(`[cleanup-cv-e2e-v2] ${message}\n`);
}

function runWrangler(dbName, sql, label) {
  const result = spawnSync(
    'npx',
    ['wrangler', 'd1', 'execute', dbName, '--env', 'staging', '--remote', '--command', sql, '--json'],
    { cwd: WORKER_DIR, encoding: 'utf8' },
  );
  if (result.status !== 0) {
    throw new Error(`${label}: ${result.stderr || result.stdout || `exit=${result.status}`}`);
  }
  try {
    return JSON.parse(result.stdout);
  } catch (error) {
    throw new Error(`${label}: invalid wrangler JSON: ${error.message}`);
  }
}

function queryRows(dbName, sql, label) {
  const parsed = runWrangler(dbName, sql, label);
  return parsed?.[0]?.results ?? [];
}

function assertNumericIds(values, label) {
  if (!Array.isArray(values) || values.length === 0) throw new Error(`${label}: empty id list`);
  for (const value of values) {
    if (!Number.isInteger(Number(value)) || Number(value) <= 0) throw new Error(`${label}: invalid id ${value}`);
  }
  return values.map(Number);
}

async function main() {
  const manifestPath = process.argv[2];
  const apply = process.argv.includes('--apply');
  if (!manifestPath || !existsSync(manifestPath)) {
    throw new Error('Uso: cleanup-controle-voos-e2e-fixtures-v2.mjs <manifest.json> [--apply]');
  }

  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
  const dbName = String(manifest.dbName || '');
  if (dbName !== ALLOWED_D1_NAME || /prod|production/i.test(dbName)) {
    throw new Error(`D1 alvo nao permitido: ${dbName}`);
  }

  const empresaIds = assertNumericIds([manifest.empresaA?.id, manifest.empresaB?.id], 'empresaIds');
  const userIds = assertNumericIds(Object.values(manifest.users || {}).map((user) => user?.id), 'userIds');
  const empresaIdList = empresaIds.join(', ');
  const userIdList = userIds.join(', ');

  log(`runId=${manifest.runId} empresas=${empresaIdList} apply=${apply}`);

  const statements = [
    ['cv_voo_eventos', `DELETE FROM cv_voo_eventos WHERE empresa_id IN (${empresaIdList});`],
    ['cv_rdv_aprovacoes', `DELETE FROM cv_rdv_aprovacoes WHERE empresa_id IN (${empresaIdList});`],
    ['cv_rdv_revisoes', `DELETE FROM cv_rdv_revisoes WHERE empresa_id IN (${empresaIdList});`],
    ['cv_rdv_alertas', `DELETE FROM cv_rdv_alertas WHERE empresa_id IN (${empresaIdList});`],
    ['cv_voo_abastecimentos', `DELETE FROM cv_voo_abastecimentos WHERE empresa_id IN (${empresaIdList});`],
    ['cv_voo_tripulantes', `DELETE FROM cv_voo_tripulantes WHERE empresa_id IN (${empresaIdList});`],
    ['cv_voo_etapas', `DELETE FROM cv_voo_etapas WHERE empresa_id IN (${empresaIdList});`],
    ['cv_rdv_operacional', `DELETE FROM cv_rdv_operacional WHERE empresa_id IN (${empresaIdList});`],
    ['cv_voos', `DELETE FROM cv_voos WHERE empresa_id IN (${empresaIdList});`],
    ['cv_aeroportos', `DELETE FROM cv_aeroportos WHERE empresa_id IN (${empresaIdList});`],
    ['cv_tipos_voo', `DELETE FROM cv_tipos_voo WHERE empresa_id IN (${empresaIdList});`],
    ['cv_naturezas_voo', `DELETE FROM cv_naturezas_voo WHERE empresa_id IN (${empresaIdList});`],
    ['cv_motivos_operacionais', `DELETE FROM cv_motivos_operacionais WHERE empresa_id IN (${empresaIdList});`],
    ['aeronaves', `DELETE FROM aeronaves WHERE empresa_id IN (${empresaIdList});`],
    ['modelos_aeronave', `DELETE FROM modelos_aeronave WHERE empresa_id IN (${empresaIdList});`],
    [
      'auditoria_avancada_v2',
      `DELETE FROM auditoria_avancada_v2
       WHERE usuario_id IN (${userIdList})
          OR (tabela = 'domain_events' AND registro_id IN (
                SELECT id FROM domain_events WHERE empresa_id IN (${empresaIdList})
             ));`,
    ],
    ['auditoria', `DELETE FROM auditoria WHERE usuario_id IN (${userIdList});`],
    ['domain_events', `DELETE FROM domain_events WHERE empresa_id IN (${empresaIdList});`],
    ['refresh_tokens', `DELETE FROM refresh_tokens WHERE user_id IN (${userIdList});`],
    ['funcionarios', `DELETE FROM funcionarios WHERE empresa_id IN (${empresaIdList});`],
    ['setores', `DELETE FROM setores WHERE empresa_id IN (${empresaIdList});`],
    ['usuarios_empresas', `DELETE FROM usuarios_empresas WHERE empresa_id IN (${empresaIdList});`],
    ['usuarios', `DELETE FROM usuarios WHERE id IN (${userIdList});`],
    ['empresas', `DELETE FROM empresas WHERE id IN (${empresaIdList});`],
  ];

  if (!apply) {
    for (const [label, sql] of statements) log(`[dry-run:${label}] ${sql.replace(/\s+/g, ' ').trim()}`);
    log('dry-run concluido; nenhuma escrita realizada.');
    return;
  }

  for (const [label, sql] of statements) {
    log(`delete:${label}`);
    runWrangler(dbName, sql, `cleanup:${label}`);
  }

  const verification = queryRows(
    dbName,
    `SELECT
       (SELECT COUNT(*) FROM empresas WHERE id IN (${empresaIdList})) AS empresas_restantes,
       (SELECT COUNT(*) FROM usuarios WHERE id IN (${userIdList})) AS usuarios_restantes,
       (SELECT COUNT(*) FROM refresh_tokens WHERE user_id IN (${userIdList})) AS refresh_tokens_restantes,
       (SELECT COUNT(*) FROM funcionarios WHERE empresa_id IN (${empresaIdList})) AS funcionarios_restantes,
       (SELECT COUNT(*) FROM setores WHERE empresa_id IN (${empresaIdList})) AS setores_restantes,
       (SELECT COUNT(*) FROM domain_events WHERE empresa_id IN (${empresaIdList})) AS domain_events_restantes;`,
    'cleanup:verify',
  )[0];

  const remaining = {
    empresas: Number(verification?.empresas_restantes ?? -1),
    usuarios: Number(verification?.usuarios_restantes ?? -1),
    refreshTokens: Number(verification?.refresh_tokens_restantes ?? -1),
    funcionarios: Number(verification?.funcionarios_restantes ?? -1),
    setores: Number(verification?.setores_restantes ?? -1),
    domainEvents: Number(verification?.domain_events_restantes ?? -1),
  };
  log(`verify ${Object.entries(remaining).map(([key, value]) => `${key}=${value}`).join(' ')}`);
  if (Object.values(remaining).some((value) => value !== 0)) {
    throw new Error(`CLEANUP_POSTCONDITION_FAILED:${JSON.stringify(remaining)}`);
  }

  rmSync(dirname(manifestPath), { recursive: true, force: true });
  log(`Manifest removido apos postconditions verdes: ${manifestPath}`);
  log('Cleanup concluido.');
}

main().catch((error) => {
  log(`ERRO: ${error.message}`);
  process.exitCode = 1;
});
